package main
import("os";"regexp";"strings";"testing")
func readVisualGrammarAsset(t *testing.T,path string)string{t.Helper();b,err:=os.ReadFile(path);if err!=nil{t.Fatal(err)};return string(b)}
func TestSharedVisualGrammarBelongsToCanonicalApp(t *testing.T){html:=readVisualGrammarAsset(t,"web/index.html");grammar:=readVisualGrammarAsset(t,"web/app/shell.css");if !strings.Contains(html,`/app/shell.css`)||!strings.Contains(html,`/app/core.js`)||!strings.Contains(html,`/app/runtime.js`){t.Fatal("canonical app assets not wired")};for _,want:=range []string{".s24-instruments",".s24-ledger",".s24-feed",".s24-table",".s24-graph",".s24-bars",".s24-pipeline",".s24-context",".s24-activity","prefers-reduced-motion:reduce"}{if !strings.Contains(grammar,want){t.Fatalf("visual grammar missing %q",want)}};for _,bad:=range []string{"javascript:","expression("}{if strings.Contains(strings.ToLower(grammar),bad){t.Fatalf("unsafe CSS %q",bad)}};if regexp.MustCompile(`content\s*:\s*["'][^"']+`).MatchString(grammar){t.Fatal("CSS must not inject explanatory copy")}}
func TestEvidenceMappingsAreDistributedByDomain(t *testing.T){orient:=requireProductScript(t,"web/app/lenses/orient-investigate.js");compare:=requireProductScript(t,"web/app/lenses/compare.js");system:=requireProductScript(t,"web/app/lenses/system.js");act:=requireProductScript(t,"web/app/lenses/act-limits.js");checks:=map[string][]string{orient:{"renderStatus","renderSnapshot","renderCases","renderSearch","renderRelations","renderAudit","renderObject","Current instruments","Review queue","Relationship field","Observed evidence relationships"},compare:{"renderChanges","renderBehavior","renderReference","Observed changes"},system:{"renderMachine","renderProcesses","renderStartup","renderStorage","Measured footprint"},act:{"renderReclaim","renderSafeChange","renderVisibility","renderGuide","Safety gate","Investigation model"}};for src,wants:=range checks{for _,want:=range wants{if !strings.Contains(src,want){t.Fatalf("domain module missing %q",want)}}}}
func TestStorageVisualizationUsesObservedNumbers(t *testing.T){js:=requireProductScript(t,"web/app/lenses/system.js");for _,want:=range []string{"files_visited","dirs_visited","visible_bytes","permission_errors","duplicate_hash_bytes","large_files","duplicates","families","hash_bytes_done","hash_bytes_total","phase_percent"}{if !strings.Contains(js,want){t.Fatalf("storage visualization missing %q",want)}};for _,want:=range []string{"exact duplicate group(s) use hash agreement","possible version family/families are naming heuristics only"}{if !strings.Contains(js,want){t.Fatalf("storage semantics missing %q",want)}}}
func TestDefaultProductDoesNotLoadRetiredGrammar(t *testing.T){html:=readVisualGrammarAsset(t,"web/index.html");for _,retired:=range []string{"v23-navigation","v23-visual-system","v23-quantitative-viz","easy.css","scan-center.css","style.css","desktop-ui.css","controller.js"}{if strings.Contains(html,retired){t.Fatalf("default product loads retired grammar/runtime %q",retired)}}}
